    13→      version = "~> 3.2"
    14→    }
    15→  }
    16→}
    17→
    18→resource "proxmox_virtual_environment_container" "lxc" {
    19→  node_name   = var.proxmox_node
    20→  vm_id       = var.container_id
    21→  description = var.description
    22→  tags        = var.tags
    23→
    24→  # Template
    25→  operating_system {
    26→    template_file_id = var.template
    27→    type             = var.os_type
    28→  }
    29→
    30→  # Compute
    31→  cpu {
    32→    cores = var.cores
    33→  }
    34→
    35→  memory {
    36→    dedicated = var.memory
    37→    swap      = var.swap
    38→  }
    39→
    40→  # Root filesystem
    41→  disk {
    42→    datastore_id = var.rootfs_storage
    43→    size         = var.rootfs_size
    44→  }
    45→
    46→  # Additional mount points
    47→  dynamic "mount_point" {
    48→    for_each = var.mount_points
    49→    content {
    50→      volume = mount_point.value.volume
    51→      path   = mount_point.value.path
    52→      backup = mount_point.value.backup
    53→      quota  = mount_point.value.quota
    54→    }
    55→  }
    56→
    57→  # Network
    58→  network_interface {
    59→    name   = "eth0"
    60→    bridge = var.network_bridge
    61→  }
    62→
    63→  initialization {
    64→    hostname = var.name
    65→
    66→    ip_config {
    67→      ipv4 {
    68→        address = var.ip_address != "" ? var.ip_address : "dhcp"
    69→        gateway = var.ip_address != "" ? var.gateway : null
    70→      }
    71→    }
    72→
    73→    user_account {
    74→      keys = [var.ssh_public_key]
    75→    }
    76→  }
    77→
    78→  # GPU Device Passthrough (AMD Radeon 890M)
    79→  dynamic "device_passthrough" {
    80→    for_each = var.enable_gpu ? [1] : []
    81→    content {
    82→      path = "/dev/dri/card0"
    83→      gid  = 44 # video group
    84→    }
    85→  }
    86→
    87→  dynamic "device_passthrough" {
    88→    for_each = var.enable_gpu ? [1] : []
    89→    content {
    90→      path = "/dev/dri/renderD128"
    91→      gid  = 104 # render group
    92→    }
    93→  }
    94→
    95→  dynamic "device_passthrough" {
    96→    for_each = var.enable_gpu ? [1] : []
    97→    content {
    98→      path = "/dev/kfd"
    99→    }
   100→  }
   101→
   102→  # Additional custom device passthrough
   103→  dynamic "device_passthrough" {
   104→    for_each = var.devices
   105→    content {
   106→      path = device_passthrough.value.path
   107→      gid  = device_passthrough.value.gid
   108→    }
   109→  }
