# =============================================================================
# Immich Importer LXC - Photo Import & Cloud Backup
# =============================================================================
# Container ID: 303 (existing)
# Purpose: Run immich-go for Google Photos import, rclone for B2 cloud backup
# =============================================================================

# -----------------------------------------------------------------------------
# App-specific Variables
# -----------------------------------------------------------------------------

variable "container_id" {
  description = "Container ID for immich-importer LXC"
  type        = number
  default     = 303
}

variable "cores" {
  description = "CPU cores"
  type        = number
  default     = 2
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 4096
}

variable "rootfs_size" {
  description = "Root filesystem size in GB"
  type        = number
  default     = 64
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 512
}

# Backblaze B2 credentials (from 1Password)
variable "b2_account_id" {
  description = "Backblaze B2 account ID"
  type        = string
  sensitive   = true
}

variable "b2_application_key" {
  description = "Backblaze B2 application key"
  type        = string
  sensitive   = true
}

variable "rclone_crypt_password" {
  description = "Rclone crypt password (obscured)"
  type        = string
  sensitive   = true
}

variable "rclone_crypt_password2" {
  description = "Rclone crypt salt (obscured)"
  type        = string
  sensitive   = true
}

# Immich configuration
variable "immich_server" {
  description = "Immich server URL"
  type        = string
  default     = "http://192.168.1.222:2283"
}

variable "immich_api_key" {
  description = "Immich API key for uploads"
  type        = string
  sensitive   = true
}

# Cloud backup schedule
variable "cloud_backup_schedule" {
  description = "Cron schedule for cloud backup (default: Wed and Sun at 3 AM)"
  type        = string
  default     = "0 3 * * 0,3"
}

# -----------------------------------------------------------------------------
# LXC Base Module
# -----------------------------------------------------------------------------

module "lxc" {
  source = "../../modules/lxc-base"

  name         = "immich-importer"
  container_id = var.container_id
  proxmox_node = var.proxmox_node

  ssh_public_key = local.ssh_public_key

  cores  = var.cores
  memory = var.memory
  swap   = var.swap

  rootfs_storage = "nvme-containers"
  rootfs_size    = var.rootfs_size

  # Ubuntu template (matches existing container)
  template = "local:vztmpl/ubuntu-24.04-standard_24.04-2_amd64.tar.zst"
  os_type  = "ubuntu"

  # Container features
  unprivileged   = true
  enable_nesting = true
  enable_keyctl  = true

  # Mount points for photos and imports
  mount_points = [
    {
      slot   = 0
      volume = "/tank/photos"
      path   = "/photos"
      backup = false
      quota  = false
    },
    {
      slot   = 1
      volume = "/tank/cache/immich"
      path   = "/cache"
      backup = false
      quota  = false
    },
    {
      slot   = 2
      volume = "/tank/importer"
      path   = "/importer"
      backup = false
      quota  = false
    },
    {
      slot   = 3
      volume = "/tank/photo-import"
      path   = "/downloads"
      backup = false
      quota  = false
    }
  ]

  tags = ["opentofu", "immich-importer", "backup", "rclone"]
}

# -----------------------------------------------------------------------------
# Wait for container to be ready
# -----------------------------------------------------------------------------

resource "time_sleep" "wait_for_container" {
  depends_on      = [module.lxc]
  create_duration = "10s"
}

# Get container IP
data "external" "container_ip" {
  depends_on = [time_sleep.wait_for_container]

  program = ["bash", "-c", <<-EOF
    IP=$(ssh -o StrictHostKeyChecking=no -i ${var.ssh_private_key_path} root@${var.proxmox_ssh_host} \
      "pct exec ${var.container_id} -- hostname -I | awk '{print \$1}'" 2>/dev/null)
    echo "{\"ip\": \"$IP\"}"
  EOF
  ]
}

locals {
  container_ip = data.external.container_ip.result.ip
}

# -----------------------------------------------------------------------------
# Install Dependencies (rclone, immich-go)
# -----------------------------------------------------------------------------

resource "null_resource" "install_dependencies" {
  depends_on = [time_sleep.wait_for_container]

  triggers = {
    container_id = var.container_id
  }

  connection {
    type        = "ssh"
    host        = local.container_ip
    user        = "root"
    private_key = file(var.ssh_private_key_path)
  }

  provisioner "remote-exec" {
    inline = [
      "export DEBIAN_FRONTEND=noninteractive",
      "apt-get update -qq",
      "apt-get install -y -qq curl unzip cron",

      # Install rclone
      "if ! command -v rclone &>/dev/null; then curl -fsSL https://rclone.org/install.sh | bash; fi",

      # Install immich-go (latest release)
      "if ! command -v immich-go &>/dev/null; then",
      "  IMMICH_GO_VERSION=$(curl -fsSL https://api.github.com/repos/simulot/immich-go/releases/latest | grep tag_name | cut -d'\"' -f4)",
      "  curl -fsSL https://github.com/simulot/immich-go/releases/download/$${IMMICH_GO_VERSION}/immich-go_Linux_x86_64.tar.gz | tar -xzf - -C /usr/local/bin immich-go",
      "  chmod +x /usr/local/bin/immich-go",
      "fi",

      # Create directories
      "mkdir -p /root/.config/rclone",
      "mkdir -p /var/log",
    ]
  }
}

# -----------------------------------------------------------------------------
# Configure rclone
# -----------------------------------------------------------------------------

resource "null_resource" "configure_rclone" {
  depends_on = [null_resource.install_dependencies]

  triggers = {
    container_id    = var.container_id
    b2_account_id   = var.b2_account_id
    crypt_password  = var.rclone_crypt_password
    crypt_password2 = var.rclone_crypt_password2
  }

  connection {
    type        = "ssh"
    host        = local.container_ip
    user        = "root"
    private_key = file(var.ssh_private_key_path)
  }

  provisioner "remote-exec" {
    inline = [
      <<-RCLONE
      cat > /root/.config/rclone/rclone.conf << 'CONF'
[b2]
type = b2
account = ${var.b2_account_id}
key = ${var.b2_application_key}
hard_delete = true

[b2-crypt]
type = crypt
remote = b2:rambtech-homelab/photos-encrypted
password = ${var.rclone_crypt_password}
password2 = ${var.rclone_crypt_password2}
CONF
      chmod 600 /root/.config/rclone/rclone.conf
      RCLONE
    ]
  }
}

# -----------------------------------------------------------------------------
# Deploy Cloud Sync Script
# -----------------------------------------------------------------------------

resource "null_resource" "deploy_cloud_sync" {
  depends_on = [null_resource.configure_rclone]

  triggers = {
    container_id = var.container_id
    script_hash  = filesha256("${path.module}/deploy/cloud-sync.sh")
  }

  connection {
    type        = "ssh"
    host        = local.container_ip
    user        = "root"
    private_key = file(var.ssh_private_key_path)
  }

  provisioner "file" {
    source      = "${path.module}/deploy/cloud-sync.sh"
    destination = "/usr/local/bin/cloud-sync.sh"
  }

  provisioner "remote-exec" {
    inline = [
      "chmod +x /usr/local/bin/cloud-sync.sh"
    ]
  }
}

# -----------------------------------------------------------------------------
# Configure Cron Job for Cloud Backup
# -----------------------------------------------------------------------------

resource "null_resource" "configure_cron" {
  depends_on = [null_resource.deploy_cloud_sync]

  triggers = {
    container_id = var.container_id
    schedule     = var.cloud_backup_schedule
  }

  connection {
    type        = "ssh"
    host        = local.container_ip
    user        = "root"
    private_key = file(var.ssh_private_key_path)
  }

  provisioner "remote-exec" {
    inline = [
      # Remove existing cloud-sync cron entries
      "crontab -l 2>/dev/null | grep -v 'cloud-sync.sh' | crontab - || true",

      # Add new cron entry
      "(crontab -l 2>/dev/null; echo '${var.cloud_backup_schedule} /usr/local/bin/cloud-sync.sh photos >> /var/log/cloud-sync-photos.log 2>&1') | crontab -",

      # Ensure cron service is running
      "systemctl enable cron",
      "systemctl start cron",

      "echo 'Cron configured: ${var.cloud_backup_schedule}'"
    ]
  }
}

# -----------------------------------------------------------------------------
# Proxmox Notes
# -----------------------------------------------------------------------------

module "proxmox_notes" {
  source     = "../../modules/proxmox-notes"
  depends_on = [null_resource.configure_cron]

  container_id         = var.container_id
  proxmox_host         = "homelab"
  ssh_private_key_path = var.ssh_private_key_path

  service_name = "Immich Importer"
  description  = "Photo import (immich-go) and cloud backup (rclone to B2)"

  urls = {}

  services = [
    { name = "immich-go", port = 0, info = "Google Photos importer" },
    { name = "rclone", port = 0, info = "Cloud backup to B2 (encrypted)" }
  ]

  ssh_host = local.container_ip

  custom_notes = "Cloud backup schedule: ${var.cloud_backup_schedule} (Wed and Sun 3 AM EST / America/New_York). Commands: task cloud:sync:photos, task cloud:status:photos, task cloud:logs:photos"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "container_id" {
  value = var.container_id
}

output "ip_address" {
  value = local.container_ip
}

output "ssh_command" {
  value = "ssh root@${local.container_ip}"
}

output "cloud_backup_schedule" {
  value = var.cloud_backup_schedule
}

# =============================================================================
# Required Variables
# =============================================================================

variable "name" {
  description = "Name/hostname of the LXC container"
  type        = string
}

variable "container_id" {
  description = "Proxmox container ID (VMID)"
  type        = number
}

# =============================================================================
# Proxmox Connection
# =============================================================================

variable "proxmox_node" {
  description = "Proxmox node to create the container on"
  type        = string
}

variable "ssh_public_key" {
  description = "SSH public key content for root access"
  type        = string
}

# =============================================================================
# Compute Resources
# =============================================================================

variable "cores" {
  description = "Number of CPU cores"
  type        = number
  default     = 1
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 512
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 512
}

# =============================================================================
# Storage Configuration
# =============================================================================

variable "rootfs_storage" {
  description = "Storage pool for root filesystem"
  type        = string
  default     = "local-lvm"
}

variable "rootfs_size" {
  description = "Root filesystem size in GB"
  type        = number
  default     = 8
}

variable "mount_points" {
  description = "Additional mount points (bind mounts from host)"
  type = list(object({
    slot    = number                 # Mount point slot (0-255)
    path    = string                 # Path inside container (e.g., /tank/media)
    volume  = string                 # Host path or volume (e.g., /tank/media)
    size    = optional(string, null) # Size if creating new volume
    storage = optional(string, null) # Storage pool if creating new volume
    backup  = optional(bool, false)
    quota   = optional(bool, false)
  }))
  default = []
}

# =============================================================================
# Network Configuration
# =============================================================================

variable "network_bridge" {
  description = "Network bridge to attach to"
  type        = string
  default     = "vmbr0"
}

variable "ip_address" {
  description = "Static IP address in CIDR notation (e.g., 192.168.1.100/24). Leave empty for DHCP."
  type        = string
  default     = ""
}

variable "gateway" {
  description = "Default gateway IP. Required if using static IP."
  type        = string
  default     = "192.168.1.1"
}

# =============================================================================
# Device Passthrough
# =============================================================================

variable "enable_gpu" {
  description = "Enable AMD GPU passthrough (/dev/dri/card0, /dev/dri/renderD128, /dev/kfd)"
  type        = bool
  default     = false
}

variable "devices" {
  description = "Additional devices to pass through to the container"
  type = list(object({
    path = string
    gid  = optional(number, null)
  }))
  default = []
}

# =============================================================================
# Template Configuration
# =============================================================================

variable "template" {
  description = "LXC template to use (e.g., local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "os_type" {
  description = "OS type (debian, ubuntu, alpine, etc.)"
  type        = string
  default     = "debian"
}

# =============================================================================
# Container Features
# =============================================================================

variable "unprivileged" {
  description = "Run as unprivileged container"
  type        = bool
  default     = true
}

variable "enable_nesting" {
  description = "Enable nesting (required for Docker/Podman)"
  type        = bool
  default     = false
}

variable "enable_fuse" {
  description = "Enable FUSE support"
  type        = bool
  default     = false
}

variable "enable_keyctl" {
  description = "Enable keyctl (required for some containers)"
  type        = bool
  default     = false
}

variable "start_on_boot" {
  description = "Start container on host boot"
  type        = bool
  default     = true
}

variable "start_on_create" {
  description = "Start container after creation"
  type        = bool
  default     = true
}

# =============================================================================
# Metadata
# =============================================================================

variable "description" {
  description = "Container description (supports markdown)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags for the container"
  type        = list(string)
  default     = []
}

# =============================================================================
# Import Configuration
# =============================================================================

variable "imported" {
  description = "Set to true for imported containers to ignore create-time-only attributes that would force replacement"
  type        = bool
  default     = false
}

# =============================================================================
# Proxmox Host SSH (for privileged container configuration)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers with apparmor)"
  type        = string
  default     = ""
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
  default     = ""
}

