     1→# =============================================================================
     2→# Provider Versions and Configuration
     3→# =============================================================================
     4→# This file is symlinked into each app directory.
     5→# Providers use secrets from 1Password via local.op.* (defined in onepassword.tf)
     6→# =============================================================================
     7→
     8→terraform {
     9→  required_version = ">= 1.7.0"
    10→
    11→  required_providers {
    12→    proxmox = {
    13→      source  = "bpg/proxmox"
    14→      version = "~> 0.69"
    15→    }
    16→    onepassword = {
    17→      source  = "1password/onepassword"
    18→      version = "~> 2.1"
    19→    }
    20→    cloudflare = {
    21→      source  = "cloudflare/cloudflare"
    22→      version = "~> 4.0"
    23→    }
    24→    local = {
    25→      source  = "hashicorp/local"
    26→      version = "~> 2.5"
    27→    }
    28→    null = {
    29→      source  = "hashicorp/null"
    30→      version = "~> 3.2"
    31→    }
    32→    time = {
    33→      source  = "hashicorp/time"
    34→      version = "~> 0.12"
    35→    }
    36→    random = {
    37→      source  = "hashicorp/random"
    38→      version = "~> 3.6"
    39→    }
    40→    # Custom providers for file sync and docker compose management
    41→    filesync = {
    42→      source  = "darshan-rambhia/filesync"
    43→      version = "~> 0.3"
    44→    }
    45→    remotedockercompose = {
    46→      source  = "darshan-rambhia/remote-docker-compose-file"
    47→      version = "~> 0.3"
    48→    }
    49→  }
    50→
    51→  # Encrypted local state - safe to commit to git
    52→  # Note: state_encryption_passphrase must be provided via TF_VAR
    53→  # because encryption runs before providers are initialized
    54→  encryption {
    55→    key_provider "pbkdf2" "main" {
    56→      passphrase = var.state_encryption_passphrase
    57→    }
    58→
    59→    method "aes_gcm" "default" {
    60→      keys = key_provider.pbkdf2.main
    61→    }
    62→
