    75→# -----------------------------------------------------------------------------
    76→# 1Password Provider
    77→# -----------------------------------------------------------------------------
    78→# Authentication via CLI with biometric unlock
    79→# Requires: op CLI v2.23.0+, signed in account
    80→
    81→provider "onepassword" {
    82→  # Uses biometric authentication via 1Password CLI
    83→  # Set OP_ACCOUNT env var or account field to your 1Password account URL
    84→  account = "rambhia.1password.com"
    85→}
    86→
    87→# -----------------------------------------------------------------------------
