    89→# -----------------------------------------------------------------------------
    90→# API token fetched from 1Password
    91→
    92→provider "proxmox" {
    93→  endpoint  = var.proxmox_endpoint
    94→  api_token = local.op.proxmox_api_token
    95→  insecure  = true
    96→
    97→  ssh {
    98→    agent       = true
    99→    username    = "root"
   100→    private_key = file(var.ssh_private_key_path)
   101→  }
   102→}
   103→
   104→# -----------------------------------------------------------------------------
   105→# Cloudflare Provider
   106→# -----------------------------------------------------------------------------
   107→# API token fetched from 1Password
   108→
   109→provider "cloudflare" {
   110→  api_token = local.op.cloudflare_api_token
   111→}
   112→
   113→# -----------------------------------------------------------------------------
   114→# Filesync Provider
   115→# -----------------------------------------------------------------------------
   116→# SSH-based file synchronization to remote hosts
   117→
   118→provider "filesync" {
